from pathlib import Path
import json,hashlib
# Manual, visually checked primary-source observations; rebuilds the ledger and hashes.
R=Path(__file__).resolve().parents[1]
def asset(p,url=None):
 b=(R/p).read_bytes();d={'path':p,'sha256':hashlib.sha256(b).hexdigest(),'bytes':len(b)}
 if url:d['url']=url
 return d
